DROP TABLE IF EXISTS `sales_sale`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_sale` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `number` bigint unsigned NOT NULL,
  `status` varchar(20) NOT NULL,
  `total_amount` decimal(28,2) NOT NULL,
  `paid_amount` decimal(28,2) NOT NULL,
  `idempotency_key` varchar(100) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `cancelled_at` datetime(6) DEFAULT NULL,
  `branch_id` bigint NOT NULL,
  `cancelled_by_id` bigint DEFAULT NULL,
  `company_id` bigint NOT NULL,
  `created_by_id` bigint NOT NULL,
  `order_id` bigint DEFAULT NULL,
  `customer_id` bigint DEFAULT NULL,
  `origin` varchar(10) NOT NULL,
  `warehouse_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sale_company_number` (`company_id`,`number`),
  UNIQUE KEY `uniq_sale_company_idempotency_key` (`company_id`,`idempotency_key`),
  UNIQUE KEY `order_id` (`order_id`),
  KEY `sales_sale_branch_id_269e60a5_fk_organizations_branch_id` (`branch_id`),
  KEY `sales_sale_cancelled_by_id_5b3a548d_fk_accounts_user_id` (`cancelled_by_id`),
  KEY `sales_sale_created_by_id_f6773268_fk_accounts_user_id` (`created_by_id`),
  KEY `sales_sale_customer_id_2d66a408_fk_customers_customer_id` (`customer_id`),
  KEY `sales_sale_warehouse_id_1c879624_fk_organizations_warehouse_id` (`warehouse_id`),
  KEY `sale_co_origin_created_idx` (`company_id`,`origin`,`created_at` DESC),
  KEY `sale_co_branch_number_idx` (`company_id`,`branch_id`,`number` DESC),
  CONSTRAINT `sales_sale_branch_id_269e60a5_fk_organizations_branch_id` FOREIGN KEY (`branch_id`) REFERENCES `organizations_branch` (`id`),
  CONSTRAINT `sales_sale_cancelled_by_id_5b3a548d_fk_accounts_user_id` FOREIGN KEY (`cancelled_by_id`) REFERENCES `accounts_user` (`id`),
  CONSTRAINT `sales_sale_company_id_6e88f52f_fk_organizations_company_id` FOREIGN KEY (`company_id`) REFERENCES `organizations_company` (`id`),
  CONSTRAINT `sales_sale_created_by_id_f6773268_fk_accounts_user_id` FOREIGN KEY (`created_by_id`) REFERENCES `accounts_user` (`id`),
  CONSTRAINT `sales_sale_customer_id_2d66a408_fk_customers_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customers_customer` (`id`),
  CONSTRAINT `sales_sale_order_id_0c146bf8_fk_orders_order_id` FOREIGN KEY (`order_id`) REFERENCES `orders_order` (`id`),
  CONSTRAINT `sales_sale_warehouse_id_1c879624_fk_organizations_warehouse_id` FOREIGN KEY (`warehouse_id`) REFERENCES `organizations_warehouse` (`id`),
  CONSTRAINT `sale_number_greater_than_zero` CHECK ((`number` > 0)),
  CONSTRAINT `sale_paid_amount_not_negative` CHECK ((`paid_amount` >= 0)),
  CONSTRAINT `sale_paid_amount_not_over_total` CHECK ((`paid_amount` <= `total_amount`)),
  CONSTRAINT `sale_total_amount_not_negative` CHECK ((`total_amount` >= 0)),
  CONSTRAINT `sales_sale_chk_1` CHECK ((`number` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=71 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

